<script setup lang="ts">
import{onMounted,ref}from'vue';import{MediaRecorderAdapter}from'../adapters/media-recorder.adapter';import{WebAudioAnalyzerAdapter}from'../adapters/web-audio-analyzer.adapter';import{WebAudioCropperAdapter}from'../adapters/web-audio-cropper.adapter';import{CanvasCoverRendererAdapter}from'../adapters/canvas-cover-renderer.adapter';import{IndexedDbMemeRepository}from'../adapters/indexeddb-meme.repository';import{BrowserShareAdapter}from'../adapters/browser-share.adapter';import{useStudio,type StudioDependencies}from'./useStudio';import RecorderPanel from'./components/RecorderPanel.vue';import CropTimeline from'./components/CropTimeline.vue';import EmotionPanel from'./components/EmotionPanel.vue';import CoverWorkshop from'./components/CoverWorkshop.vue';import MemeGallery from'./components/MemeGallery.vue';import SharePanel from'./components/SharePanel.vue';
const props=defineProps<{dependencies?:StudioDependencies}>();const defaults:StudioDependencies={recorder:new MediaRecorderAdapter(),analyzer:new WebAudioAnalyzerAdapter(),cropper:new WebAudioCropperAdapter(),renderer:new CanvasCoverRendererAdapter(),repository:new IndexedDbMemeRepository(),share:new BrowserShareAdapter()};const studio=useStudio(props.dependencies??defaults);const recording=ref(false);async function start(){await studio.startRecording();recording.value=!studio.error.value}async function stop(){await studio.stopRecording();recording.value=false}onMounted(()=>studio.loadCollection());
</script>
<template><div class="sound-app"><header><div class="logo">声<span>!</span></div><div><small>SOUND REACTION STUDIO / 005</small><h1>声音表情包工坊</h1></div><nav><button v-for="(s,i) in ['录音','裁剪','情绪','封面','作品集']" :key="s" :class="{active:['record','crop','emotion','cover','collection'][i]===studio.stage.value}">{{ i+1 }} {{ s }}</button></nav></header><main><section class="intro"><div><span class="kicker">MAKE SOME NOISE. MAKE IT YOURS.</span><h2>让声音，<em>长出表情。</em></h2><p>录一句、认情绪、做封面。十秒就能生成一张会发声的表情包。</p></div><div class="intro-badge"><b>10</b><span>SECONDS<br>OF ATTITUDE</span></div></section><div v-if="studio.error.value" class="error-banner">{{studio.error.value}}</div><div v-if="studio.notice.value" class="notice-banner">{{studio.notice.value}}</div><RecorderPanel v-if="studio.stage.value==='record'" :recording="recording" :level="studio.level.value" @record="start" @stop="stop" @import="studio.importAudio"/><CropTimeline v-else-if="studio.stage.value==='crop'" :duration="studio.draft.duration" :start="studio.draft.cropStart" :end="studio.draft.cropEnd" @update-start="studio.draft.cropStart=$event" @update-end="studio.draft.cropEnd=$event" @analyze="studio.analyze"/><EmotionPanel v-else-if="studio.stage.value==='emotion'&&studio.emotion.value" :result="studio.emotion.value" @select="studio.selectEmotion" @next="studio.goCover"/><CoverWorkshop v-else-if="studio.stage.value==='cover'" :config="studio.cover.value" :title="studio.draft.title" @patch="studio.cover.value={...studio.cover.value,...$event}" @title="studio.draft.title=$event" @save="studio.save()"/><MemeGallery v-else :items="studio.collection.value" @edit="studio.editMeme" @remove="studio.deleteMeme" @share="studio.shareMeme" @new="studio.newRecording"/><SharePanel/></main></div></template>
